head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.gExplDisclsAcptNo;
scwin.gExplDisclsOrdNo;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gInputTp;
scwin.vScrenID = 'ULDSTF30222.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_resizeToWin = function() {
    frame.Width = 560;
    frame.Height = 290;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !정보--;
셋팅-- > function() {
    scwin.gExplDisclsAcptNo = $c.frame.path("../").scwin.gExplDisclsAcptNo;
    scwin.gExplDisclsOrdNo = $c.frame.path("../").scwin.gExplDisclsOrdNo;
    //alert("자식창:"+gExplDisclsAcptNo+","+ gExplDisclsOrdNo);

} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/ExplanationDisclosure.do?method=readExplReDsclDetail" + "&inputMessageId=EXPLDISCLSREAD_INOUT" + "&outputMessageId=EXPLDISCLSREAD_INOUT" + "&EXPLDISCLS_ACPT_NO=" + scwin.gExplDisclsAcptNo + "&EXPLDISCLS_ORD_NO=" + scwin.gExplDisclsOrdNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_explanation_info.DataID = encodeURI(url);
    dts_explanation_info.reset();
};
scwin.fn_Update = function() {
    if ($c.stf.getObjectValue(txa_remk).length > 200) {
        $c.win.alert("비고는  200자이하만 입력할 수 있습니다.");
        return false;
    }
    dts_explanation.insertRow();
    dts_explanation.setCellData(1, "EXPLDISCLS_ACPT_NO", scwin.gExplDisclsAcptNo);
    dts_explanation.setCellData(1, "EXPLDISCLS_ORD_NO", scwin.gExplDisclsOrdNo);
    dts_explanation.setCellData(1, "REG_ID", js_emp_no);
    dts_explanation.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));

    //alert(dts_nfaith.text);

    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        trs_explanation_info.Action = "/ExplanationDisclosure.do?method=modifyExplanationReDscl&inputMessageId=EXPLDISCLSREAD_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_explanation_info.KeyName = "toinb_dataid4";
        trs_explanation_info.KeyValue = "JSP(I:pInput=dts_explanation)";
        trs_explanation_info.Post();
    }
};




// 답변연결 삭제(담당자가 수동으로 연결한것)
scwin.fn_Delete = function() {
    if (scwin.gInputTp == 'A') {
        $c.win.alert("상장법인이 제출한 해명공시는 삭제하실 수 없습니다.");
        //edt_deadline_dd.focus();
        return;
    }
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_explanation.insertRow();
        dts_explanation.setCellData(1, "EXPLDISCLS_ACPT_NO", scwin.gExplDisclsAcptNo);
        dts_explanation.setCellData(1, "EXPLDISCLS_ORD_NO", scwin.gExplDisclsOrdNo);
        trs_explanation_info.Action = "/ExplanationDisclosure.do?method=removeExplanationReDscl&inputMessageId=EXPLDISCLSREAD_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_explanation_info.KeyName = "toinb_dataid4";
        trs_explanation_info.KeyValue = "JSP(I:pInput=dts_explanation)";
        trs_explanation_info.Post();
    }
};
scwin.btn_Close_onclick = async function() {
    //self.close();
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Update();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.dts_explanation_info_OnLoadError = function() {
    $c.stf.alert_error(dts_explanation_info);
};
scwin.dts_explanation_info_OnLoadCompleted = function(rowcount) {
    var vProcsEmpNo = dts_explanation_info.getCellData(1, "REG_ID");
    if (vProcsEmpNo == 'SYSTEM_Y' || vProcsEmpNo == 'SYSTEM_N') {
        scwin.gInputTp = 'A'; // 상장법인이 제출한 경우
        $c.stf.showObj(btn_Delete, false);
    } else {
        scwin.gInputTp = 'M'; // 신규 등록한 경우
        $c.stf.showObj(btn_Delete, true);
    }
};
scwin.trs_explanation_info_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    //self.close();
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_reload();
};
scwin.trs_explanation_info_OnFail = function() {
    $c.win.alert('trs_explanation_info.OnFail() :' + trs_explanation_info.ErrorMsg);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_resizeToWin();
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_explanation_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=EXPLDISCLSREAD_INOUT";
    dts_explanation_info.reset();
    // 가우스헤더 셋팅
    dts_explanation.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=EXPLDISCLSREAD_INOUT";
    dts_explanation.reset();

    //  정보 읽어오기
    fn_ReadInfo();
};
